export function AustraliaAtlas({page=0,capitals=false,focus}:{page?:number;capitals?:boolean;focus?:string}){
 const [picked,setPicked]=useState("");const selected=picked||focus||stateInfo[Math.max(0,page-1)%stateInfo.length].name;
 const state=stateInfo.find(s=>s.name===selected)||stateInfo[0];
 return <div><p style={{textAlign:"center",fontWeight:800}}>Australia — states, territories and capitals</p>
 <CountryMap box="861 286 170 157" highlight={["Australia"]} markers={[]}>
 <g clipPath="url(#australia-clip)">{stateLines.map((d,i)=><path key={i} d={d} fill="none" stroke="#fff" strokeWidth="1.1"/>)}</g>
 {stateInfo.filter(s=>s.short!=="ACT").map(s=><g key={s.short} onClick={()=>setPicked(s.name)} style={{cursor:"pointer"}}><circle cx={X(s.cx)} cy={Y(s.cy)} r="8" fill={selected===s.name?"#7352d3":"transparent"}/><text x={X(s.cx)} y={Y(s.cy)+1.5} fontSize="6" fontWeight="900" textAnchor="middle" fill={selected===s.name?"white":"#43334e"}>{s.short}</text></g>)}
 <circle cx={X(state.lon)} cy={Y(state.lat)} r="2.5" fill="#7938a8" stroke="white" strokeWidth=".7"/>
 <text x={X(state.lon)+4} y={Y(state.lat)-3} fontSize="6" fontWeight="800" fill="#392452" stroke="white" strokeWidth="1.4" paintOrder="stroke">{state.capital}</text>
 </CountryMap>
 <div style={{display:"flex",flexWrap:"wrap",justifyContent:"center",gap:6,marginTop:10}}>{stateInfo.map(s=><button type="button" key={s.short} onClick={()=>setPicked(s.name)} style={{padding:"7px 9px",borderRadius:12,border:"1px solid #b9b4d3",background:selected===s.name?"#e0d6ff":"white",color:"#27253b",fontWeight:700}}>{s.short}</button>)}</div>
 <p style={{textAlign:"center",fontWeight:800}}>{state.name} — {state.capital}</p>
 {state.short==="ACT"&&<p style={{textAlign:"center",fontSize:13}}>Canberra is in the small Australian Capital Territory, inside southeastern New South Wales.</p>}
 </div>;
}
export function RegionAtlas({unitId,page=0}:{unitId:string;page?:number}){
 const r=regionInfo[unitId];if(!r)return null;const [picked,setPicked]=useState("");const target=r.names[Math.max(0,page-1)%r.names.length];const active=picked||target;const marker=r.capitals.find(x=>x[0]===active);const capitalMarkers: [string,number,number][]=marker?[[marker[1],marker[2],marker[3]]]:[];
 return <div><p style={{fontWeight:800,textAlign:"center"}}>Explore {unitId.replace("geo-","").replace("-"," ")}</p><CountryMap box={r.box} highlight={[active]} onCountry={n=>{if(r.names.includes(n))setPicked(n)}} markers={capitalMarkers}/><div style={{display:"flex",flexWrap:"wrap",gap:6,justifyContent:"center",marginTop:10}}>{r.names.map(n=><button type="button" key={n} onClick={()=>setPicked(n)} style={{padding:"7px 9px",border:"1px solid #bbb5d4",borderRadius:12,background:active===n?"#e0d6ff":"white",color:"#29253a",fontSize:12,fontWeight:700}}>{countryName(n)}</button>)}</div><p style={{textAlign:"center",fontWeight:700}}>{countryName(active)}{marker?" — "+marker[1]:""}</p></div>;
}
export function OceanAtlas(){const [active,setActive]=useState("");const oceans:[string,number,number][]=[["Pacific",85,280],["Pacific",995,280],["Atlantic",465,290],["Indian",750,340],["Southern",600,470],["Arctic",550,47]];return <div><p style={{textAlign:"center",fontWeight:800}}>The world's five oceans</p><CountryMap>{oceans.map(([name,x,y],i)=><g key={i} role="button" tabIndex={0} onClick={()=>setActive(name)} onKeyDown={e=>{if(e.key==="Enter")setActive(name)}} style={{cursor:"pointer"}}><text x={x} y={y} textAnchor="middle" fontSize={name==="Southern"?34:36} fontWeight="800" fill={active===name?"#5d3ca9":"#164b73"} stroke="#cde9f9" strokeWidth="4" paintOrder="stroke">{name}</text></g>)}</CountryMap><p style={{textAlign:"center",fontSize:13}}>{active?active+" Ocean":"Tap an ocean name. The Pacific appears on both edges of the map because Earth is round."}</p></div>}
export function AustraliaWorld({page=0}:{page?:number}){if(page===4)return <AustraliaAtlas focus="Australian Capital Territory"/>;return <div><p style={{textAlign:"center",fontWeight:800}}>Australia in the Southern Hemisphere</p><CountryMap box="650 160 420 290" highlight={["Australia"]}>{page===0||page===5?<><path d="M650 270H1070" stroke="#9c3d85" strokeWidth="2" strokeDasharray="7 4"/><text x="660" y="265" fontSize="12" fontWeight="800" fill="#6e316a">Equator</text><text x="760" y="420" fontSize="14" fontWeight="800" fill="#39346c">Southern Hemisphere</text></>:null}<text x="730" y="338" fontSize="18" fontWeight="800" fill="#164b73">Indian Ocean</text><text x="1012" y="330" textAnchor="middle" fontSize="19" fontWeight="800" fill="#164b73">Pacific Ocean</text></CountryMap><p style={{textAlign:"center",fontSize:13}}>Australia is south of the Equator. Indian Ocean to the west; Pacific Ocean to the east.</p></div>}
